{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C48"],
      "claim": "Verapamil, a dimethoxyphenyl tertiary-amine analogue, showed absolute oral bioavailability of 52.3% in cirrhotic patients, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "In volunteers, (+)-verapamil had an absolute oral bioavailability of about 50%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Noscapine, a related dimethoxyisoquinoline alkaloid, has an absolute oral bioavailability of about 30% in humans, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Valbenazine, sharing the dimethoxytetrahydroisoquinoline core, has an absolute oral bioavailability of approximately 49% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Colchicine, a methoxyphenyl amide with P-gp efflux liability, has a mean absolute oral bioavailability of about 45%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Clomipramine, a tricyclic with a dimethylaminopropyl side chain, has a human oral bioavailability of about 50%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Donepezil, a structurally similar dimethoxy aromatic amine, has essentially complete oral bioavailability (≈100%).",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple structurally related analogues with high transfer scores (verapamil, noscapine, valbenazine, colchicine, clomipramine, donepezil) consistently show absolute oral bioavailability ≥30%, well above the 20% threshold. The only low-F records involve verapamil under rifampicin co-treatment, a condition not applicable to the query. The mixed physicochemical prior is overridden by the consistent experimental evidence.",
  "evidence_gaps": [
    "No direct pharmacokinetic data for the query molecule itself.",
    "The highest-transfer verapamil evidence was obtained in cirrhotic patients, which may overestimate F relative to healthy conditions, though baseline verapamil F is still ≥20%.",
    "The query's susceptibility to CYP3A4-mediated first-pass metabolism is unknown; rifampicin-induction records for verapamil are not applicable to baseline F.",
    "The effect of the low neutral fraction (0.02) on intestinal permeability is not directly measured."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C48"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "verapamil"
    },
