      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "noscapine"
    },
    {
      "applicability": "high",
      "card_ids": ["C26"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "valbenazine"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C07"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "colchicine"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C08"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "clomipramine"
    },
    {
      "applicability": "high",
      "card_ids": ["C45"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "donepezil"
    },
    {
